		t.Run("debug mode keeps an unknown member", func(t *testing.T) {
			file := filepath.Join(t.TempDir(), "interactions.json")

			c, err := NewClient(WithBaseURL(apitest.BodyServer(t, http.StatusOK, "application/json", apitest.WithUnknownMember(t, ListDataSourceTemplatesOk{}, jsonOpts))), WithDebugFile(file))
			if err != nil {
				t.Fatal(err)
			}

			for range 2 {
				if _, err := c.ListDataSourceTemplates(t.Context(), uuid.Nil(), nil); err != nil {
					t.Fatalf("debug mode decodes leniently: %v", err)
				}
			}

			if ias, err := cassette.InteractionsReadFile(file); err != nil {
				t.Fatal(err)
			} else if len(ias) != 1 {
				t.Fatalf("the debug file holds %d calls, want the one that failed to decode, once", len(ias))
			}
		})

